9. PrintWindow reusable snippet (must Add-Type each PS session): Add-Type @"
using System; using System.Drawing; using System.Runtime.InteropServices;
public class WCap {
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, int f);
    [StructLayout(LayoutKind.Sequential)] public struct RECT{public int L,T,R,B;}
    public static void Cap(IntPtr hwnd,string path){RECT r;GetWindowRect(hwnd,out r);int w=r.R-r.L,h=r.B-r.T;var b=new System.Drawing.Bitmap(w,h);var g=System.Drawing.Graphics.FromImage(b);PrintWindow(hwnd,g.GetHdc(),2);g.ReleaseHdc();g.Dispose();b.Save(path);b.Dispose();}
}
"@ -ReferencedAssemblies System.Drawing ; [WCap]::Cap([IntPtr]0xHWND, 'C:\tmp\out.png')
